import numpy as np

def make_input(agent=None, reward=None, obstacle=None, moving=None, prev=None):
    x = np.zeros((10,10,5), dtype=float)
    for r in range(10):
        for c in range(10):
            if r==0 or r==9 or c==0 or c==9:
                x[r,c,3] = 1.0
    if agent   is not None: x[agent[0],   agent[1],   0] = 1.0
    if reward  is not None: x[reward[0],  reward[1],  2] = 1.0
    if obstacle is not None: x[obstacle[0],obstacle[1],3] = 1.0
    if moving  is not None: x[moving[0],  moving[1],  1] = 1.0
    if prev is not None:
        for p in prev:
            x[p[0], p[1], 4] = 1.0
    return x.flatten()

scen, lab = [], []

# 1) agent-only position sweep over the 3x3 inner anchor grid
for r in [1,4,8]:
    for c in [1,4,8]:
        scen.append(make_input(agent=(r,c))); lab.append(f"agent_r{r}c{c}")

# 2) far rewards (distance 2) around centre agent
for dr,dc,nm in [(-2,0,'up2'),(2,0,'down2'),(0,-2,'left2'),(0,2,'right2'),
                 (-2,-2,'UL2'),(-2,2,'UR2'),(2,-2,'DL2'),(2,2,'DR2')]:
    scen.append(make_input(agent=(4,4), reward=(4+dr,4+dc))); lab.append(f"reward_{nm}")

# 3) corner-to-corner reward (does a far goal pull the agent?)
scen.append(make_input(agent=(8,8), reward=(1,1))); lab.append("agent_r8c8_rew_r1c1")
scen.append(make_input(agent=(1,1), reward=(8,8))); lab.append("agent_r1c1_rew_r8c8")

# 4) far moving objects (distance 2) around centre agent
for dr,dc,nm in [(-2,0,'up2'),(2,0,'down2'),(0,-2,'left2'),(0,2,'right2')]:
    scen.append(make_input(agent=(4,4), moving=(4+dr,4+dc))); lab.append(f"moving_{nm}")

# 5) previous-frame (velocity) probes: agent at centre, prev cell at a neighbour
for dr,dc,nm in [(-1,0,'above'),(1,0,'below'),(0,-1,'left'),(0,1,'right')]:
    scen.append(make_input(agent=(4,4), prev=[(4+dr,4+dc)])); lab.append(f"prev_{nm}")

X = np.array(scen)
out = forward(X)

print("action order: 0 noop, 1 up, 2 down, 3 left, 4 right")
print(f"{'label':24s} {'noop':>7s} {'up':>7s} {'down':>7s} {'left':>7s} {'right':>7s}  argmax")
for l,o in zip(lab,out):
    print(f"{l:24s} {o[0]:7.2f} {o[1]:7.2f} {o[2]:7.2f} {o[3]:7.2f} {o[4]:7.2f}  {int(np.argmax(o))}")

# summary: up-noop gap across the position sweep, to check for any row/col trend
print("\nposition sweep up-noop gap:")
for l,o in zip(lab[:9],out[:9]):
    print(f"  {l:16s} up-noop = {o[1]-o[0]:+.2f}")

import numpy as np
from collections import defaultdict

def make_obs(agent, reward=None):
    x = np.zeros(500)
    def setc(r, c, ch, v=1):
        x[(r * 10 + c) * 5 + ch] = v
    for r in range(10):
        for c in range(10):
            if r == 0 or r == 9 or c == 0 or c == 9:
                setc(r, c, 3, 1)
    setc(agent[0], agent[1], 0, 1)
    setc(agent[0], agent[1], 4, 1)  # previous frame = same agent position
    if reward is not None:
        setc(reward[0], reward[1], 2, 1)
    return x

positions = [(2, 2), (2, 7), (7, 2), (7, 7)]
dirs = [('U', -1, 0, 1, 2), ('D', 1, 0, 2, 1),
        ('L', 0, -1, 3, 4), ('R', 0, 1, 4, 3)]

Xs, meta = [], []
for ar, ac in positions:
    Xs.append(make_obs((ar, ac)))
    meta.append(('base', (ar, ac), None, None, None))
    for name, dr, dc, tow, away in dirs:
        rr, cc = ar + dr, ac + dc
        if 1 <= rr <= 8 and 1 <= cc <= 8:
            Xs.append(make_obs((ar, ac), (rr, cc)))
            meta.append((name, (ar, ac), tow, away, (rr, cc)))

out = forward(np.vstack(Xs))
base_logits = {}
for i, m in enumerate(meta):
    if m[0] == 'base':
        base_logits[m[1]] = out[i]

print("action order: 0 noop, 1 up, 2 down, 3 left, 4 right")
print("pos dir argmax attraction")
attrs = defaultdict(list)
overall = []
for i, m in enumerate(meta):
    name, pos, tow, away, reward = m
    if name == 'base':
        print(f"{pos} base argmax={int(np.argmax(out[i]))} logits={np.round(out[i], 2)}")
    else:
        d = out[i] - base_logits[pos]
        attr = d[tow] - d[away]
        attrs[name].append(attr)
        overall.append(attr)
        print(f"{pos} {name} argmax={int(np.argmax(out[i]))} attr={attr:+.2f}")

print("mean attraction by direction:")
for name, _, _, _, _ in dirs:
    if attrs[name]:
        print(name, f"{np.mean(attrs[name]):+.2f}", "n=", len(attrs[name]))
print("overall mean attraction", f"{np.mean(overall):+.2f}",
      "positive fraction", f"{np.mean(np.array(overall) > 0):.2f}")
